1: import React, { useCallback, useState } from 'react';
2: import { useTranslation } from 'react-i18next';
3: import { Button, InlineLoading, ModalBody, ModalFooter, ModalHeader } from '@carbon/react';
4: import { showSnackbar } from '@openmrs/esm-framework';
5: import { deletePatientAllergy, useAllergies } from './allergy-intolerance.resource';
6: 
7: interface DeleteAllergyModalProps {
8:   closeDeleteModal: () => void;
9:   allergyId: string;
10:   patientUuid?: string;
11: }
12: 
13: const DeleteAllergyModal: React.FC<DeleteAllergyModalProps> = ({ closeDeleteModal, allergyId, patientUuid }) => {
14:   const { t } = useTranslation();
15:   const { mutate } = useAllergies(patientUuid);
16:   const [isDeleting, setIsDeleting] = useState(false);
17: 
18:   const handleDelete = useCallback(async () => {
19:     if (!patientUuid) {
20:       console.error('DeleteAllergyModal opened without patientUuid');
21:       return;
22:     }
23: 
24:     setIsDeleting(true);
25: 
26:     try {
27:       await deletePatientAllergy(patientUuid, allergyId, new AbortController());
28:       void mutate();
29:       closeDeleteModal();
30:       showSnackbar({
31:         isLowContrast: true,
32:         kind: 'success',
33:         title: t('allergyDeleted', 'Allergy deleted'),
34:       });
35:     } catch (error) {
36:       console.error('Error deleting allergy: ', error);
37:       showSnackbar({
38:         isLowContrast: false,
39:         kind: 'error',
40:         title: t('errorDeletingAllergy', 'Error deleting allergy'),
41:         subtitle: error?.message,
42:       });
43:     } finally {
